  "claims": [
    {
      "claim": "The term was given by ancient Athenians to those who informed on the exportation of figs contrary to law.",
      "tag": "enduring",
      "quote_britannica": "an appellation given by the ancient Atheman to thole who informed the exporation of figs contary to bay",
      "quote_wikipedia": "Plutarch appears to be the first to have suggested that the source of the term was in laws forbidding the exportation of figs, and that those who leveled the accusation against another of illegally exporting figs were therefore called sycophants"
    },
    {
      "claim": "The term came to be used generally for all informers, parasites, flatterers, and chests.",
      "tag": "enduring",
      "quote_britannica": "and hence it is full field in general for all inforners, parafities, flattreets, chests, &c.",
      "quote_wikipedia": "In modern English, sycophant denotes an insincere flatterer and refers to someone practising sycophancy"
    },
    {
      "claim": "The word originates from the Greek words for fig and to show, meaning revealer of figs.",
      "tag": "enduring",
      "quote_britannica": "the exporation of figs contary to bay",
      "quote_wikipedia": "The original etymology of the word (sykos / συκος ' fig ', and phanēs / φανης 'to show'; 'revealer of figs') has been the subject of extensive scholarly speculation"
    },
    {
      "claim": "The word entered English and French in the mid-16th century with the original meaning of false accuser.",
      "tag": "enduring",
      "quote_britannica": "an appellation given by the ancient Atheman to thole who informed",
      "quote_wikipedia": "The word sycophant entered the English and French languages in the mid-16th century, and originally had the same meaning in English and French as in Greek, a false accuser"
    },
    {
      "claim": "The meaning in English shifted to mean an insincere flatterer.",
      "tag": "enduring",
      "quote_britannica": "and hence it is full field in general for all inforners, parafities, flattreets, chests, &c.",
      "quote_wikipedia": "The meaning in English has changed over time, however, and came to mean an insincere flatterer"
    },
    {
      "claim": "In Modern Greek, French, and Italian the word retains the meaning of slanderer or false accuser.",
      "tag": "enduring",
      "quote_britannica": "an appellation given by the ancient Atheman to thole who informed",
      "quote_wikipedia": "The word retains the same meaning ('slanderer') in Modern Greek, French (where sycophant means 'false accuser', or professional ' informer '), and Italian"
